<script setup>
import ListPagination from '../../shared/components/ListPagination.vue'
import DataTable from "../../shared/components/DataTable.vue"

import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()


import {computed, inject, nextTick, onBeforeUnmount, ref, watch} from 'vue';


import ListFilters from '../../shared/components/ListFilters.vue';
import {browserView} from '../../shared/viewMemory.js';
const props=defineProps({type:{type:String,required:true},active:Boolean,me:{type:Object,default:()=>({})},services:{type:Array,default:()=>[]},canManage:{type:Function,required:true}});
const emit=defineEmits(['view','edit','version','action','preview','deliver','create','work']);
const api=inject('api'),query=ref(''),status=ref(''),kind=ref(''),service=ref(''),owner=ref(''),association=ref('');
const items=ref([]),owners=ref([]),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),error=ref(''),ownersError=ref(''),selected=ref([]),scroll=ref(null);
let sequence=0,timer,loaded=false,position=null;
let memory,restoring=false,viewActor='',viewEpoch=0,disposed=false,ownersSequence=0;
const viewDefaults={q:'',status:'',kind:'',service:'',owner:'',association:'',page:1,size:20};
const viewState=()=>({q:query.value,status:status.value,kind:kind.value,service:service.value,owner:owner.value,association:association.value,page:page.value,size:pageSize.value});
function rememberView(){if(memory&&!restoring)memory.write(viewState(),viewDefaults)}
const advanced=ref(false);
const advancedCount=computed(()=>[owner.value,association.value].filter(Boolean).length);
const isVersion=computed(()=>props.type==='versions');
const endpoint=computed(()=>isVersion.value?'release-versions':'changes');
const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)));
const filtered=computed(()=>!!(query.value||status.value||kind.value||service.value||owner.value||association.value));
const mineAvailable=computed(()=>!!props.me.username&&props.me.username!=='local'&&props.me.auth_enabled!==false);
const mine=computed(()=>mineAvailable.value&&owner.value===props.me.username);
const ownerOptions=computed(()=>[...new Set([...owners.value,...(owner.value?[owner.value]:[])])].map(value=>({value,label:value})));
const statusOptions=computed(()=>isVersion.value?[{value:'draft',label:'草稿'},{value:'ready',label:'已冻结'},{value:'completed',label:'已完成'},{value:'canceled',label:'已取消'}]:[{value:'draft',label:'草稿'},{value:'ready',label:'已就绪'},{value:'archived',label:'已归档'}]);
const kindOptions=[{value:'code',label:'代码分支'},{value:'artifact',label:'应用制品'},{value:'mysql',label:'SQL / 数据同步'},{value:'nacos',label:'Nacos 配置'},{value:'redis',label:'Redis 命令'},{value:'manual',label:'自定义记录'}];
const kindLabel=v=>v.data_sync?'数据同步':v.kind==='mysql'?'SQL 变更':kindOptions.find(k=>k.value===v.kind)?.label||v.kind;
const statusLabel=v=>v.missing_branch?'草稿 · 待补分支':statusOptions.value.find(s=>s.value===v.status)?.label||v.status;
const date=value=>value?new Date(value*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const allSelected=computed(()=>!!items.value.length&&selected.value.length===items.value.length);
const canEdit=item=>props.canManage(item)&&item.status==='draft'&&!item.frozen&&!item.data_sync;
function selectRow(item,checked){selected.value=checked?[...new Set([...selected.value,item.id])]:selected.value.filter(id=>id!==item.id)}
function selectPage(checked){selected.value=checked?items.value.map(v=>v.id):[]}
function clearSelection(){selected.value=[]}
async function loadPage(){
 clearTimeout(timer);loaded=true;const request=++sequence;loading.value=true;error.value='';items.value=[];clearSelection();
 const params=new URLSearchParams({page:String(page.value),page_size:String(pageSize.value),q:query.value,status:status.value,kind:kind.value,service:service.value,owner:owner.value,association:association.value});
 try{const result=await api(`api/${endpoint.value}/page?${params}`);if(request!==sequence)return;
  if(!Array.isArray(result?.items)||!Number.isInteger(result.total)||!Number.isInteger(result.page))throw new Error('列表响应格式错误，请刷新重试');
  items.value=result.items;total.value=result.total;page.value=result.page;
 }catch(e){if(request===sequence){error.value=e.message;total.value=0}}
 finally{if(request===sequence)loading.value=false}
}
async function loadOwners(){const request=++ownersSequence;try{const result=await api(`api/${endpoint.value}/owners`);if(request!==ownersSequence||disposed)return;if(!Array.isArray(result))throw new Error();owners.value=result;ownersError.value=''}catch{if(request===ownersSequence&&!disposed)ownersError.value='创建人列表加载失败，可刷新重试'}}
function refresh(){if(!loaded&&!props.active)return;loadPage();loadOwners()}
function goto(value){page.value=value;loadPage();if(scroll.value)scroll.value.scrollTop=0}
function clearFilters(){query.value='';status.value='';kind.value='';service.value='';owner.value='';association.value=''}
function rememberPosition(){const area=scroll.value?.querySelector('[data-slot=table-container]')||scroll.value;position={top:area?.scrollTop||0,left:area?.scrollLeft||0,outer:scroll.value?.closest('main')?.scrollTop||0}}
async function restorePosition(){if(!position||!props.active)return;await nextTick();if(scroll.value){const area=scroll.value.querySelector('[data-slot=table-container]')||scroll.value;area.scrollTop=position.top;area.scrollLeft=position.left;const main=scroll.value.closest('main');if(main)main.scrollTop=position.outer}}
function command(op,item){if(op==='version')emit('version',item);else if(op==='preview')emit('preview',item);else if(['ready','reopen','delete'].includes(op))emit('action',{item,op})}
watch(query,()=>{if(!loaded||restoring)return;page.value=1;sequence++;items.value=[];clearSelection();loading.value=true;clearTimeout(timer);timer=setTimeout(loadPage,300)});
watch([status,kind,service,owner,association,pageSize],()=>{if(!loaded||restoring)return;page.value=1;loadPage()});
watch([query,status,kind,service,owner,association,page,pageSize],rememberView,{flush:'post'});
watch(()=>[props.active,props.me.username],async ([active,actor])=>{
 const epoch=++viewEpoch;if(!actor)return;
 if(actor!==viewActor){sequence++;ownersSequence++;items.value=[];owners.value=[];clearSelection();restoring=true;viewActor=actor;memory=browserView('deploy:'+props.type,actor);const v=memory.read(viewDefaults);query.value=v.q;status.value=v.status;kind.value=v.kind;service.value=v.service;owner.value=v.owner;association.value=v.association;page.value=v.page;pageSize.value=[20,50,100].includes(v.size)?v.size:20;loaded=false}
 await nextTick();if(disposed||epoch!==viewEpoch)return;restoring=false;
 if(active&&!loaded){loadPage();loadOwners()}else if(active)restorePosition()
},{immediate:true});
onBeforeUnmount(()=>{rememberView();disposed=true;viewEpoch++;sequence++;ownersSequence++;clearTimeout(timer)});
defineExpose({refresh,rememberPosition,restorePosition,clearSelection});

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Badge,Button,Checkbox,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldLabel,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><section :aria-label="isVersion?'发布版本列表':'变更记录'" class="delivery-list"><ListFilters v-model="advanced" :active-count="advancedCount"><InputGroup  class="min-w-0 search"><InputGroupInput v-model="query" :placeholder="isVersion?'搜索版本号、标题或说明':'搜索标题、应用或引用'" v-bind="{'aria-label':isVersion?'搜索发布版本':'搜索变更'}"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="query" :disabled="false" size="icon-xs" aria-label="清空输入" @click="query='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-if="!isVersion" v-model="kind" :options="kindOptions" all-label="全部类型" :style="{width:'120px',maxWidth:'100%'}" aria-label="变更类型"/><OptionPicker v-model="status" :options="statusOptions" all-label="全部状态" :style="{width:'120px',maxWidth:'100%'}" aria-label="记录状态"/><OptionPicker v-model="service" :options="services.map(v=>({value:v.name,label:v.display_name||v.name}))"  all-label="全部应用" :style="{width:'140px',maxWidth:'100%'}" aria-label="筛选应用"/><template #actions><Button :title="mineAvailable?'按当前账号筛选创建人':'登录后使用；也可直接选择创建人'" @click="owner=mine?'':me.username" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[mine?'primary':'secondary']||'outline'" size="default" type="button" :disabled="(!mineAvailable)">只看我的</Button><Button v-if="filtered" @click="clearFilters" variant="ghost" size="default" type="button">清空筛选</Button><Button @click="refresh" variant="outline" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>刷新</Button></template><template #advanced><Field ><FieldLabel as="div">创建人</FieldLabel><OptionPicker v-model="owner" :options="ownerOptions"  all-label="全部创建人" :style="{width:'170px',maxWidth:'100%'}" aria-label="筛选创建人"/></Field><Field v-if="!isVersion"><FieldLabel as="div">关联关系</FieldLabel><OptionPicker v-model="association" :options="[{value:'linked',label:'关联需求 / BUG'},{value:'independent',label:'独立变更'}]" all-label="全部关联" :style="{width:'170px',maxWidth:'100%'}" aria-label="关联关系"/></Field></template></ListFilters><p v-if="ownersError" role="alert" class="hint">{{ownersError}}</p><div v-if="selected.length&&!isVersion" role="status" class="selection">已选择本页 {{selected.length}} 项<Button @click="emit('version',items.filter(v=>selected.includes(v.id)))" variant="default" size="sm" type="button">批量纳入版本</Button><Button @click="emit('deliver',{ids:[...selected]})" variant="outline" size="sm" type="button">交付所选变更</Button><Button @click="clearSelection" variant="ghost" size="sm" type="button">取消选择</Button></div><div ref="scroll" tabindex="0" :aria-label="isVersion?'版本表格，可滚动':'变更表格，可滚动'" :aria-busy="loading" class="table-scroll"><div :class="['console-table',['records-table',{versions:isVersion}]]" class="min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({minWidth:isVersion?1144:1440}).y?({minWidth:isVersion?1144:1440}).y+'px':undefined}"><DataTable :rows="(((items)||[]).map((item,rowIndex)=>({...item,__rowKey:item.id}))||[])" :columns="[{id:'c0',label:&quot;选择&quot;,size:40,minSize:40,required:true,defaultHidden:false,flex:false,selection:true,pin:'left',enabled:(!isVersion)},{id:'c1',label:(isVersion?'版本 / 名称':'变更标题'),size:220,minSize:160,required:true,defaultHidden:false,flex:true,selection:false,pin:'left'},{id:'c2',label:(isVersion?'版本状态':'状态'),size:isVersion?112:88,minSize:isVersion?112:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c3',label:&quot;类型&quot;,size:Math.max(80,Math.min(160,140)),minSize:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false,enabled:(!isVersion)},{id:'c4',label:(isVersion?'交付范围':'应用'),size:isVersion?240:160,minSize:isVersion?240:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c5',label:&quot;关联需求 / BUG&quot;,size:Math.max(80,Math.min(160,220)),minSize:64,required:false,defaultHidden:true,flex:false,selection:false,pin:false,enabled:(!isVersion)},{id:'c6',label:&quot;创建人&quot;,size:96,minSize:80,required:false,defaultHidden:!isVersion,flex:false,selection:false,pin:false},{id:'c7',label:&quot;更新时间&quot;,size:128,minSize:112,required:false,defaultHidden:!isVersion,flex:false,selection:false,pin:false},{id:'c8',label:&quot;操作&quot;,size:176,minSize:176,required:true,defaultHidden:false,flex:false,selection:false,pin:'right'}]" :table-key="'deploy-components-DeliveryRecordsTable-0:'+type" :row-key="(record,rowIndex)=>typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><template #header-c0><Checkbox  :disabled="loading||!items.length" aria-label="选择本页全部变更" @update:model-value="selectPage($event)" :model-value="selected.length>0&&!allSelected?'indeterminate':allSelected"/></template><template #cell-c0="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Checkbox :model-value="selected.includes(item.id)" :aria-label="`选择变更 ${item.title}`" @update:model-value="(value=>selectRow(item,value))($event)"/></div></template></div></template><template #header-c1>{{isVersion?'版本 / 名称':'变更标题'}}</template><template #cell-c1="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div class="record-title"><Button :title="isVersion?`${item.version} · ${item.title}`:item.title" @click="emit('view',item)" class="title-link" variant="ghost" size="sm" type="button">{{isVersion?item.version:item.title}}</Button><small :title="isVersion?item.title:''" :class="{'record-id':!isVersion}">{{isVersion?item.title:`#${item.id}`}}</small></div></template></div></template><template #header-c2>{{isVersion?'版本状态':'状态'}}</template><template #cell-c2="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Badge :variant="(item.status==='completed'?'green':item.status==='ready'?'blue':'gray')==='red'?'destructive':'secondary'">{{statusLabel(item)}}</Badge><small v-if="item.frozen">随版本冻结</small></div></template></div></template><template #header-c3>类型</template><template #cell-c3="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Badge variant="secondary">{{kindLabel(item)}}</Badge></div></template></div></template><template #header-c4>{{isVersion?'交付范围':'应用'}}</template><template #cell-c4="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><template v-if="isVersion"><div :title="'应用数包含代码、配置等所有关联应用；交付结果按环境查看'">{{item.application_count}} 应用 · {{item.work_item_count}} 工作项 · {{item.change_count}} 变更</div></template><template v-else><div :title="item.service">{{item.service||'—'}}</div></template></template></div></template><template #header-c5>关联需求 / BUG</template><template #cell-c5="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div><template v-if="item.work_items?.length"><Button :title="item.work_items.map(w=>w.title).join('、')" @click="emit('work',item.work_items[0])" class="related-link" variant="ghost" size="sm" type="button">{{item.work_items[0].external_id||`#${item.work_items[0].id}`}} · {{item.work_items[0].title}}</Button><small v-if="item.work_items.length>1">另 {{item.work_items.length-1}} 项 · 详情查看全部</small></template><span v-else class="muted">独立变更</span></div></template></div></template><template #header-c6>创建人</template><template #cell-c6="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div :title="item.owner">{{item.owner||'—'}}</div></template></div></template><template #header-c7>更新时间</template><template #cell-c7="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div :title="item.updated_at?new Date(item.updated_at*1000).toLocaleString('zh-CN'):''">{{date(item.updated_at)}}</div></template></div></template><template #header-c8>操作</template><template #cell-c8="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:item,rowIndex:rowIndex} in [{record,rowIndex}]"><div class="fixed-actions"><div class="cell-actions flex-nowrap!"><Button v-if="!isVersion&&item.status==='ready'" @click="emit('deliver',item)" variant="ghost" size="sm" type="button">预览发布</Button><Button v-else-if="item.missing_branch&&canEdit(item)" @click="emit('edit',item)" variant="ghost" size="sm" type="button">补填分支</Button><Button v-else-if="!isVersion" @click="emit('view',item)" variant="ghost" size="sm" type="button">查看</Button><Button v-else-if="canEdit(item)" @click="emit('edit',item)" variant="ghost" size="sm" type="button">编辑范围</Button><Button v-else-if="['ready','completed'].includes(item.status)" @click="emit('deliver',item)" variant="ghost" size="sm" type="button">发起交付</Button><Button v-else @click="emit('view',item)" variant="ghost" size="sm" type="button">查看</Button><DropdownMenu><DropdownMenuTrigger as-child><Button :aria-label="`${item.title}的更多操作`" class="more" variant="ghost" size="sm" type="button">更多 ▾</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem v-if="isVersion||item.status==='ready'||item.missing_branch&&canEdit(item)" @select="emit('view',item)">查看详情</DropdownMenuItem><DropdownMenuItem v-if="!isVersion&&canEdit(item)" @select="emit('edit',item)">编辑变更</DropdownMenuItem><DropdownMenuItem v-if="!isVersion&&item.status!=='ready'" @select="emit('deliver',item)">发起交付</DropdownMenuItem><DropdownMenuItem v-if="!isVersion" @select="command('version',item)">纳入版本</DropdownMenuItem><DropdownMenuItem v-if="!isVersion&&['mysql','nacos','redis'].includes(item.kind)" @select="command('preview',item)">{{item.kind==='mysql'?'SQL 预检':item.kind==='nacos'?'Nacos 差异预览':'Redis 命令预检'}}</DropdownMenuItem><DropdownMenuItem v-if="canManage(item)&&item.status==='draft'&&!item.frozen" @select="command('ready',item)">{{isVersion?'冻结并标记就绪':'标记就绪'}}</DropdownMenuItem><DropdownMenuItem v-if="!isVersion&&canManage(item)&&item.status==='ready'&&!item.frozen" @select="command('reopen',item)">退回草稿</DropdownMenuItem><DropdownMenuItem v-if="canManage(item)&&item.status==='draft'&&!item.frozen" @select="command('delete',item)">删除草稿</DropdownMenuItem><DropdownMenuItem v-if="isVersion&&(!canManage(item)||item.status!=='draft')" @select="emit('view',item)">其他操作见版本详情</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></div></template></div></template><template #empty><Empty><EmptyHeader><EmptyDescription><span v-if="loading" role="status">正在加载…</span><template v-else-if="error"><p role="alert">{{error}}</p><Button @click="refresh" variant="outline" size="default" type="button">重试</Button></template><template v-else-if="filtered"><p>没有符合筛选条件的记录</p><Button @click="clearFilters" variant="outline" size="default" type="button">清空筛选</Button></template><template v-else><p>尚无{{isVersion?'发布版本':'变更'}}</p><Button @click="emit('create')" variant="outline" size="default" type="button">{{isVersion?'创建版本草稿':'新建变更'}}</Button></template></EmptyDescription></EmptyHeader></Empty></template></DataTable></div></div></div><div class="table-footer"><ListPagination :page="page" :total="total" :page-size="pageSize" :disabled="loading" @update:page="goto($event)" @update:page-size="pageSize=$event"/></div></section></template>
<style scoped>.delivery-list{min-width:0}.hint{font-size:.75rem;color:var(--muted-foreground);margin:0 0 8px}.selection{display:flex;gap:12px;align-items:center;margin:0 0 10px;padding:8px 12px;background:var(--brand-soft);border-radius:var(--radius);font-size:.75rem}
.table-scroll{overflow:auto}.records-table{width:100%}.title-link,.related-link{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left}.muted{color:var(--muted-foreground)}.records-table .empty-row{text-align:center;height:160px;color:var(--muted-foreground)}.page-navigation{margin-left:auto;display:flex;align-items:center;gap:10px}
@media(max-width:700px){.search{width:100%}.page-navigation{margin-left:0;flex-wrap:wrap;gap:8px}.selection{flex-wrap:wrap}}</style>

<style scoped>.record-title{display:flex;align-items:center;gap:8px;min-width:0}.record-title:has(.record-id) .title-link{flex:0 1 auto;min-width:0}.record-id{flex-shrink:0;margin:0!important;color:var(--muted-foreground)}.versions .record-title{display:block}</style>
